import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const starBowCard='a2-p10-r2c3';
export const starBowScenarios=['star-bow-ordinary', 'star-bow-owner-ordinary', 'star-bow-low', 'star-bow-dedicated', 'star-bow-pair', 'star-bow-all', 'star-bow-near', 'star-bow-same-faction', 'star-bow-water-ordinary', 'star-bow-water-dedicated', 'star-bow-metal-ordinary', 'star-bow-metal-dedicated', 'star-bow-fort-ordinary', 'star-bow-fort-dedicated', 'star-bow-maai-one-ordinary', 'star-bow-maai-two-ordinary', 'star-bow-maai-one-dedicated', 'star-bow-maai-two-dedicated', 'star-bow-evade-ordinary', 'star-bow-evade-dedicated', 'star-bow-fate', 'star-bow-suppressed', 'star-bow-silenced', 'star-bow-stopped', 'star-bow-wrong-owner', 'star-bow-decline', 'star-bow-unprepared-ordinary', 'star-bow-unprepared-dedicated', 'star-bow-chant-ordinary', 'star-bow-chant-dedicated', 'star-bow-counter-ordinary', 'star-bow-counter-dedicated', 'star-bow-black-ordinary', 'star-bow-black-dedicated', 'star-bow-dead-ordinary', 'star-bow-dead-dedicated', 'star-bow-black-maai', 'star-bow-dead-fate', 'star-bow-white-prohibited', 'star-bow-water-blessed-ordinary', 'star-bow-water-blessed-dedicated'] as const;
export type StarBowScenario=typeof starBowScenarios[number];
export function isStarBowScenario(name:string):name is StarBowScenario{return (starBowScenarios as readonly string[]).includes(name);}
export function starBowMode(name:StarBowScenario){const suffix=name.replace('star-bow-',''),incoming=suffix.startsWith('counter-'),dedicated=!suffix.endsWith('ordinary')&&!['low','decline','white-prohibited'].includes(suffix),owner=dedicated&&suffix!=='wrong-owner'||suffix==='owner-ordinary',targets=suffix==='all'?[1,2,3]:['pair','suppressed','silenced'].includes(suffix)?[1,2]:[1],black=suffix.startsWith('black'),dead=suffix.startsWith('dead'),water=suffix.startsWith('water'),metal=suffix.startsWith('metal'),follower=black?'a2-p22-r1c2':dead?'a2-p22-r3c2':water?'a2-p23-r1c1':metal?'a2-p22-r1c1':suffix.startsWith('fort')?'a2-p19-r1c3':null,maai=suffix.includes('maai'),evade=suffix.includes('evade'),damage=dedicated?13:10,cancel=suffix.endsWith('fate');return {suffix,dedicated,owner,targets,black,dead,water,metal,follower,maai,evade,incoming,damage,cancel};}
export function makeStarBowPhysical(name:StarBowScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;prepared?:boolean;warrior?:number;spirit?:number;targetSpirit?:number}={}){
 const m=starBowMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix),incoming=m.incoming;let s=createGame(players,entropy(),{startingSeat:prior?3:m.suffix==='counter-unprepared'?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.suffix==='white-prohibited'?'不死王ガドューラ':m.owner?'妖精王フューリー':'侍大将のシン','黒妖精のアーネス',m.suffix==='same-faction'?'大神官ジル':'魔導王ガイナス','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.spirit??6:p.id===b?options.targetSpirit??11:p.id===c?12:6)-gameStats(s,p.id).spirit;}
 s.players[a]!.permanent!.warrior_level!+=(options.warrior??(m.suffix==='low'?6:m.dedicated?0:7))-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,starBowCard),takeCard(s,d,'a2-p02-r2c3')];if(m.follower)keep.push(takeCard(s,b,m.follower));if(m.black||m.dead)keep.push(takeCard(s,c,'a2-p19-r3c2'));if(m.suffix==='near')keep.push(takeCard(s,a,'a2-p24-r1c3'));if(m.maai)keep.push(takeCard(s,b,'a2-p06-r1c3'),takeCard(s,b,'a2-p06-r2c1'));if(m.evade)keep.push(takeCard(s,b,'a2-p05-r3c1'));if(incoming)keep.push(takeCard(s,b,'a2-p24-r1c2'));if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 let blessing:string|undefined;if(m.suffix.includes('blessed')){blessing=takeCard(s,b,'a2-p01-r2c1');s.players[b]!.hand=s.players[b]!.hand.filter(id=>id!==blessing);}for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];if(blessing){const prefix=s.deck.splice(0,2);s.deck=[...prefix,blessing,...s.deck];}s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`STAR_BOW_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('STAR_BOW_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('STAR_BOW_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('STAR_BOW_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if((m.black||m.dead)&&id===c)act(c,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:'a2-p19-r3c2'});if(m.follower&&id===b)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:m.follower});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));if(options.beforeStart)return s;
 if(m.suffix==='counter-unprepared'){act(b,{type:'START_TURN'});act(b,{type:'CHOOSE_DRAW',draw:false});act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let n=0;n<400;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('STAR_BOW_UNPREPARED_COUNTER');}
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 act(a,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(a,{type:'CHOOSE_DRAW',draw:false});if(['stopped','decline','white-prohibited'].includes(m.suffix)||m.suffix.startsWith('unprepared')||m.suffix.startsWith('chant-')||options.prepared===false)return s;
 act(a,{type:'CHANT',cardInstanceId:starBowCard,dedicated:['wrong-owner','counter-foreign'].includes(m.suffix)?false:m.dedicated});for(let n=0;n<250;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'},prior?6:1);else if(s.phase==='action'){if(id===a)break;if(incoming&&id===b){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let k=0;k<300;k++){if(s.windows?.at(-1)?.kind==='normal-defense')return s;const next=s.windows!.at(-1)!;act(next.participants[next.cursor]!,{type:'PASS'});}throw Error('STAR_BOW_INCOMING_LIMIT');}act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.slice(gameStats(s,id).handLimit)});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:!!blessing&&id===b});else throw Error('STAR_BOW_TURN');}
 if(m.suffix==='near'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}if(m.suffix==='same-faction'){act(c,{type:'REVEAL_CHARACTER'});settle();}return s;
}
